catalog_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
    if (isLoading || newValue == '') {
        return;
    }

    var ACTION_VAR = 'action';
    var DELETE_VALUE = 'delete';


    var actionVal = (g_form.getValue(ACTION_VAR) || '').toString().toLowerCase();
    if (actionVal !== DELETE_VALUE) {
        return;
    }
    if (!newValue) {
        g_form.setValue('location_description', '');
        //g_form.setValue('old_region', '');
        return;
    }

    var ga = new GlideAjax('HSBCTradeTaskUtils');
    ga.addParam('sysparm_name', 'getLocationCodeDetails');
    ga.addParam('sysparm_sys_id', newValue);
    ga.getXMLAnswer(handleResponse);
}

function handleResponse(answer) {
    if (!answer) return;
    var data;
    try {
        data = JSON.parse(answer);
    } catch (e) {
        return;
    }

    if (data.location_description != null) g_form.setValue('location_description', data.location_description);
    //if (data.region != null) g_form.setValue('old_region', data.region);

}
